"use client"

import type React from "react"

import { useState } from "react"
import Header from "@/components/header"
import Footer from "@/components/footer"
import { ArrowLeft, Facebook, Twitter, Linkedin, Send } from "lucide-react"
import Link from "next/link"

export default function Contact() {
  const [formData, setFormData] = useState({
    name: "",
    email: "",
    phone: "",
    message: "",
  })
  const [submitted, setSubmitted] = useState(false)

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target
    setFormData((prev) => ({ ...prev, [name]: value }))
  }

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault()
    console.log("Form submitted:", formData)
    setSubmitted(true)
    setFormData({ name: "", email: "", phone: "", message: "" })
    setTimeout(() => setSubmitted(false), 5000)
  }

  return (
    <>
      <Header />
      <main className="min-h-screen bg-background text-foreground py-16">
        <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8">
          {/* Back Button */}
          <Link href="/" className="flex items-center gap-2 text-primary hover:text-primary/80 transition mb-8">
            <ArrowLeft size={20} />
            Retour à l'accueil
          </Link>

          {/* Hero */}
          <div className="text-center mb-16">
            <h1 className="text-5xl md:text-6xl font-bold text-primary mb-4">Nous Contacter</h1>
            <p className="text-xl text-foreground/70">
              Nous sommes heureux de répondre à vos questions et de vous aider dans votre parcours spirituel.
            </p>
          </div>

          {/* Content Grid */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-12 items-start">
            {/* Contact Info */}
            <div className="space-y-8 card p-8">
              <div>
                <h2 className="text-2xl font-bold text-primary mb-6">Informations de Contact</h2>
                <div className="space-y-6">
                  <div>
                    <h3 className="font-bold text-primary mb-2">Adresse</h3>
                    <p className="text-foreground/70">Lomé, Togo</p>
                  </div>
                  <div>
                    <h3 className="font-bold text-primary mb-2">Téléphone</h3>
                    <a href="tel:+22890000000" className="text-foreground/70 hover:text-primary transition">
                      +228 90 00 00 00
                    </a>
                  </div>
                  <div>
                    <h3 className="font-bold text-primary mb-2">Email</h3>
                    <a href="mailto:info@missionagape.tg" className="text-foreground/70 hover:text-primary transition">
                      info@missionagape.tg
                    </a>
                  </div>
                  <div>
                    <h3 className="font-bold text-primary mb-2">Horaires</h3>
                    <p className="text-foreground/70">Lundi - Vendredi: 08h00 - 17h00</p>
                    <p className="text-foreground/70">Samedi: 09h00 - 12h00</p>
                  </div>
                </div>
              </div>

              {/* Social Links */}
              <div>
                <h2 className="text-2xl font-semibold text-primary mb-6">Nous Suivre</h2>
                <div className="flex gap-4">
                  <a
                    href="#"
                    aria-label="Facebook"
                    className="w-12 h-12 bg-blue-600 text-white rounded-lg flex items-center justify-center hover:bg-blue-700 transition-all shadow-sm"
                  >
                    <Facebook className="w-6 h-6" />
                  </a>
                  <a
                    href="#"
                    aria-label="X (Twitter)"
                    className="w-12 h-12 bg-gray-900 text-white rounded-lg flex items-center justify-center hover:bg-gray-800 transition-all shadow-sm"
                  >
                    <Twitter className="w-5 h-5" />
                  </a>
                  <a
                    href="#"
                    aria-label="LinkedIn"
                    className="w-12 h-12 bg-blue-700 text-white rounded-lg flex items-center justify-center hover:bg-blue-800 transition-all shadow-sm"
                  >
                    <Linkedin className="w-5 h-5" />
                  </a>
                </div>
              </div>
            </div>

            {/* Contact Form */}
            <div>
              <form onSubmit={handleSubmit} className="space-y-6 card p-8">
                <div>
                  <label htmlFor="name" className="block text-sm font-medium mb-2 text-primary">
                    Nom complet
                  </label>
                  <input
                    type="text"
                    id="name"
                    name="name"
                    value={formData.name}
                    onChange={handleChange}
                    required
                    className="w-full px-4 py-3 bg-input border border-border rounded-lg text-foreground focus:outline-none focus:ring-2 focus:ring-[var(--logo-blue)]"
                    placeholder="Votre nom"
                  />
                </div>

                <div>
                  <label htmlFor="email" className="block text-sm font-medium mb-2 text-primary">
                    Email
                  </label>
                  <input
                    type="email"
                    id="email"
                    name="email"
                    value={formData.email}
                    onChange={handleChange}
                    required
                    className="w-full px-4 py-3 bg-input border border-border rounded-lg text-foreground focus:outline-none focus:ring-2 focus:ring-[var(--logo-blue)]"
                    placeholder="votre.email@example.com"
                  />
                </div>

                <div>
                  <label htmlFor="phone" className="block text-sm font-medium mb-2 text-primary">
                    Téléphone (optionnel)
                  </label>
                  <input
                    type="tel"
                    id="phone"
                    name="phone"
                    value={formData.phone}
                    onChange={handleChange}
                    className="w-full px-4 py-3 bg-input border border-border rounded-lg text-foreground focus:outline-none focus:ring-2 focus:ring-[var(--logo-blue)]"
                    placeholder="+228 90 00 00 00"
                  />
                </div>

                <div>
                  <label htmlFor="message" className="block text-sm font-medium mb-2 text-primary">
                    Message
                  </label>
                  <textarea
                    id="message"
                    name="message"
                    value={formData.message}
                    onChange={handleChange}
                    required
                    rows={6}
                    className="w-full px-4 py-3 bg-input border border-border rounded-lg text-foreground focus:outline-none focus:ring-2 focus:ring-[var(--logo-blue)] resize-none"
                    placeholder="Votre message..."
                  />
                </div>

                <button 
                  type="submit" 
                  className="w-full bg-gradient-to-r from-blue-600 to-blue-800 text-white font-medium py-3 px-6 rounded-lg hover:from-blue-700 hover:to-blue-900 transition-all flex items-center justify-center space-x-2 shadow-md hover:shadow-lg"
                >
                  <Send className="w-5 h-5" />
                  <span>Envoyer le message</span>
                </button>

                {submitted && (
                  <div className="p-4 bg-green-500/10 border border-green-500/30 rounded-lg text-green-600">
                    Merci! Votre message a été envoyé avec succès.
                  </div>
                )}
              </form>
            </div>
          </div>
        </div>
      </main>
      <Footer />
    </>
  )
}
